    std::uint8_t aDomainWordMatrixArgC = pConstants->mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pConstants->mMatrixArgD;

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    TwistExpander_Castor_Arx::KDF_C_A_E(PARAMS_KDF);

    //
    // src: [$aether]
    // dst: [$lunar]
    //
    TwistExpander_Castor_Arx::KDF_C_B_E(PARAMS_KDF);

    //
    // ent: [$aether]
